}
async function bulkDone() {
  const ids = [...STATE.selected];
  if (!ids.length) return;
  // Animate the cards out and prune the model; archive in one parallel round trip.
  ids.forEach((id) => { removeCard(id); removeFromData(id); });
  clearSelection();
  let res;
