async function bulkThings() {
  const ids = [...STATE.selected];
  for (const id of ids) {
    const r = findRow(id) || {};
    await post("/api/to_things", { threadId: id, title: r.subject || "(email)", sender: r.sender || "", snippet: r.snippet || "" });
  }
