// Attachment chips, keyed by STATE field + list container
function renderChips(key, sel) {
  const wrap = $(sel);
  if (!wrap) return;
  wrap.innerHTML = "";
  (STATE[key] || []).forEach((f, i) => {
    const chip = document.createElement("div");
