  const t = STATE.threadCache[r.dataset.tid];
  const first = t?.messages?.[0] || {};
  const res = await post("/api/to_things", { threadId: r.dataset.tid, title: r.dataset.subject, sender: first.sender || "", snippet: (first.text || "").slice(0, 140) });
