function findRow(id) {
  const d = STATE.data;
  if (!d) return null;
  const pools = [d.pinned, d.primary, d.items, ...((d.bundles || []).map((b) => b.items))];
  for (const p of pools) { if (p) { const r = p.find((x) => x.id === id); if (r) return r; } }
  return null;
