    subject: (t.subject || "").startsWith("Fwd:") ? t.subject : "Fwd: " + (t.subject || ""),
    html: fwd,
    forwardAttachments: (last.attachments || []).map((a) => ({ ...a, messageId: a.messageId || last.id })),
  });
}
