  const m = $("#scheduleMenu"), r = e.currentTarget.getBoundingClientRect();
  m.hidden = false;
  m.style.top = Math.max(8, r.top - m.offsetHeight - 6) + "px";
  m.style.left = Math.min(r.left, window.innerWidth - 250) + "px";
};
