// ---------- Settings panel ----------
function openSettings() {
  const s = STATE.settings || {};
  $("#setSignature").innerHTML = s.signature || "";
  $("#setUndoWindow").value = String(s.undo_send_window ?? 10);
  $("#setDarkMode").value = s.dark_mode || "auto";
