  el.addEventListener("click", (e) => {
    if (e.target.closest(".actions") || e.target.closest(".unsub-link") || e.target.closest(".select") || e.target.closest(".att-chip")) return;
    openThread(row.id);
  });
  el.querySelectorAll(".att-chip").forEach((c) => {
