      `<i class="material-icons" style="font-size:16px;color:#5f6368">attach_file</i><span>${esc(a.filename)}</span>`;
    chip.querySelector("input").onchange = (e) => { STATE.fwdAttachments[i].keep = e.target.checked; };
    wrap.appendChild(chip);
