// Re-evaluate auto dark mode when the OS theme flips.
window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => {
  if ((STATE.settings.dark_mode || "auto") === "auto") applySettings(STATE.settings);
});

