    q = (request.args.get("q") or "").strip().lower()
    now = int(time.time())
    with _contacts_lock:
        if now - _contacts_cache["at"] > 900 or not _contacts_cache["list"]:
            try:
                _contacts_cache["list"] = _rebuild_contacts()
                _contacts_cache["at"] = now
