  el.addEventListener("click", (e) => {
    if (e.target.closest(".actions") || e.target.closest(".unsub-link") || e.target.closest(".select") || e.target.closest(".att-chip") || e.target.closest(".doc-chip")) return;
    openThread(row.id);
  });
