  if (token.length < 2) { dd.hidden = true; return; }
  let r;
  try { r = await api("/api/contacts?q=" + encodeURIComponent(token)); } catch (e) { return; }
  const list = (r && r.contacts) || [];
  if (!list.length) { dd.hidden = true; return; }
  dd.innerHTML = "";
  list.forEach((c) => {
