    if (btn) btn.textContent = "Unsubscribed ✓";
  } else if (r.fallbackUrl) {
    openExternal(r.fallbackUrl); toast("Finish unsubscribing in the browser");
    if (btn) { btn.disabled = false; btn.textContent = orig; }
  } else {
