function afterTriage() {
  if (!$("#reader").hidden) closeReader();
  else load();
}
async function commitSnooze(payload) {
  $("#snoozeMenu").hidden = true;
  const ids = STATE.snoozeMulti ? [...STATE.selected] : (snoozeTarget ? [snoozeTarget.id] : []);
  if (!ids.length) return;
