    $("#composeDiscard").style.display = "";
    setSaveStatus("Draft saved");
  } else {
    setSaveStatus("Couldn't save draft");
  }
  draftSaving = false;
  if (draftDirty) saveDraftNow();           // changes arrived while we were saving
}
