      dt.onchange = () => { const ep = Math.floor(new Date(dt.value).getTime() / 1000); if (ep) doComposeSend(ep); };
      dt.showPicker ? dt.showPicker() : dt.focus();
      return;
    }
    doComposeSend(resolveScheduleEpoch(s));
  };
});
